   ```ts
   import { useEffect, useLayoutEffect, useRef } from "react";

   /** R2127000: the key in `history.state` that marks an entry as this module's. */
   const BACK_ENTRY = "jackiohBackEntry";
   /** What is used of the browser's `CloseWatcher`, which lib.dom may not declare. */
   type Watcher = { onclose: ((event: Event) => void) | null; destroy(): void };
   type WatcherClass = new () => Watcher;
   type Layer = { close: () => void };

   const layers: Layer[] = []; // oldest first
   let held: { layer: Layer; watcher: Watcher } | null = null;
   let entryAt: string | null = null; // the address of this module's entry while it is current, live or spent
   let staleBelow = false; // a replacing navigate moved off the entry below: Back skips it
   let skipNext = false; // the next popstate is this module's own step back off a spent entry
   let listening = false;
   const answered = new WeakMap<Event, boolean>();

   function here(): string { return window.location.pathname + window.location.search; }
   function isBackEntry(state: unknown): boolean {
     return typeof state === "object" && state !== null && Reflect.get(state, BACK_ENTRY) === true;
   }
   function watcherClass(): WatcherClass | null {
     const found: unknown = Reflect.get(globalThis, "CloseWatcher");
     return typeof found === "function" ? (found as WatcherClass) : null;
   }

   function sync(): void {
     const top = layers.at(-1);
     const Made = watcherClass();
     if (Made !== null) {
       if (held !== null && held.layer !== top) { held.watcher.destroy(); held = null; }
       if (top === undefined || held !== null) return;
       const watcher = new Made();
       watcher.onclose = () => {
         if (held?.watcher === watcher) held = null;
         if (layers.at(-1) === top) top.close();
         queueMicrotask(sync);
       };
       held = { layer: top, watcher };
       return;
     }
     // Something else replaced the entry (a room link read off the address, a test's `at`).
     if (entryAt !== null && !isBackEntry(window.history.state)) { entryAt = null; staleBelow = false; }
     if (top === undefined || entryAt !== null) return;
     window.history.pushState({ [BACK_ENTRY]: true }, "", here());
     entryAt = here();
   }

   function answerPop(): boolean {
     if (skipNext) { skipNext = false; return true; }
     if (isBackEntry(window.history.state)) { skipNext = true; window.history.back(); return true; }
     if (entryAt === null) return false;
     const from = entryAt;
     const stale = staleBelow;
     entryAt = null;
     staleBelow = false;
     if (here() !== from && !stale) return false; // a Back of more than one step
     const top = layers.at(-1);
     if (top === undefined) window.history.back(); // a spent entry: on past the copied address
     else { top.close(); queueMicrotask(sync); }
     return true;
   }

   export function popBackLayer(event: Event): boolean {
     const known = answered.get(event);
     if (known !== undefined) return known;
     const mine = answerPop();
     answered.set(event, mine);
     return mine;
   }

   export function moveOverBackEntry(path: string, replace: boolean): boolean {
     if (entryAt === null || !isBackEntry(window.history.state)) return false;
     if (replace) { window.history.replaceState({ [BACK_ENTRY]: true }, "", path); entryAt = here(); staleBelow = true; }
     else { window.history.replaceState(null, "", path); entryAt = null; staleBelow = false; }
     queueMicrotask(sync);
     return true;
   }

   function openLayer(layer: Layer): () => void {
     if (!listening) { window.addEventListener("popstate", popBackLayer); listening = true; }
     layers.push(layer);
     sync();
     return () => {
       const at = layers.indexOf(layer);
       if (at !== -1) layers.splice(at, 1);
       sync();
     };
   }

   export function useBackLayer(close: () => void): void {
     const latest = useRef(close);
     useLayoutEffect(() => { latest.current = close; });
     useEffect(() => openLayer({ close: () => { latest.current(); } }), []);
   }
   ```

